{
    next modified();

    FormDataObject formDataObject = any2Object(this) as FormDataObject;
    FormDataSource  metSiteControllingAndSubordinateSetup_ds = formDataObject.datasource();
    METSiteControllingAndSubOrdinateSetup metSiteControllingAndSubOrdinateSetup = metSiteControllingAndSubordinateSetup_ds.cursor();

    if (metSiteControllingAndSubOrdinateSetup.ControllingSiteId)
    {
        metSiteControllingAndSubordinateSetup_ds.object(fieldNum(METSiteControllingAndSubOrdinateSetup, IsControllingSite)).allowEdit(false);
    }
    else
    {
        metSiteControllingAndSubordinateSetup_ds.object(fieldNum(METSiteControllingAndSubOrdinateSetup, IsControllingSite)).allowEdit(true);
    } 
}
